-- 0251: fold every area the source's SORT LABEL filed twice into ONE area.
--
-- Asked: "ok go" — fold the 474 areas check:area-sort-labels held (scripts/data/area-sort-labels-held.json)
-- under the standing rule "fold into 1 area, same for everything else, i don't want duplicates".
-- #2224 took the label off 3,449 area names ("a1. The Uberfall" -> "The Uberfall"). 474 could not
-- be renamed: the unlabelled name was ALREADY a sibling, or the duplicate trigger refused it — one
-- place imported twice, once under the guidebook's label and once without. Mostly the two copies hold
-- DIFFERENT climbs (the route trigger let only the missing ones into the copy), so they are two halves.
--
-- Read (2026-10-07): 421 groups. No contribution, log, photo, topo or list points at any climb or
-- area here. Plan: the unlabelled member is kept (else the one with most climbs); each copy folds in:
--   * 47 climbs stored on both sides (same name, same base grade, compatible discipline): the keeper
--     fills each BLANK column from the copy (0221's rule), takes the copy's grade only where it
--     extends the keeper's ("5.9" -> "5.9 PG13"), and the copy row is deleted.
--   * 1777 other climbs move into the keeper; 28 more share a name with a DIFFERENT climb there
--     ("Unknown" 5.6 / "Unknown" 5.5, "Headless Horseman" V7 / 5.10b) and move with the trigger bypassed.
--   * 75 sub-areas re-parented; a sub-area whose twin is under the keeper folds the same way.
--   * 393 emptied copies deleted, children first; the keeper first fills its blank columns from them.
--   * 9 groups list climbs flat in one member and sub-areas in the other: see step 2.
--   * 49 labelled keepers lose the label; 34 more are an AREA around a same-named formation
--     ("Royal Arches Area" > "Royal Arches"), which catalog_key reads as one name — renamed bypassed.
-- Not folded, accepted: spelling variants ("Hieronymus" / "Heironymous Bosch") stay two climbs.
-- ABORTS if climber data points at a climb deleted (an area's photos move to the keeper), or if the live tree no longer matches the plan.
-- Plan: built and read in a job scratch folder (not kept); rollback: scripts/data/area-sort-label-folds-rollback.json.
-- APPLIED LIVE IN PIECES (scripts/oneoff/apply-0251-in-parts.mjs): the ~1,800 moves fire three per-row
-- triggers and the one transaction outlasts the SQL gateway. That script records 0251 when it finishes.

begin;

